      // Truck cab (METAL, 2×2)
      setBlock(sgX,     txy + 1, txz,     BLOCK.METAL);
      setBlock(sgX + 1, txy + 1, txz,     BLOCK.METAL);
      setBlock(sgX,     txy + 1, txz + 1, BLOCK.METAL);
