      setBlock(sgX + 1, txy + 2, txz,     BLOCK.METAL);
      setBlock(sgX,     txy + 2, txz + 1, BLOCK.METAL);
      setBlock(sgX + 1, txy + 2, txz + 1, BLOCK.METAL);
      // Truck bed (METAL, 2×4 longer)
