      setBlock(hmX + 2 + hcx, hmY + 1, hmZ + 2, BLOCK.METAL);
      setBlock(hmX + 2 + hcx, hmY + 2, hmZ + 1, BLOCK.METAL);
      setBlock(hmX + 2 + hcx, hmY + 2, hmZ + 2, BLOCK.METAL);
